"use client";

import { useEffect, useState } from "react";
import { AnalysisPanel } from "@/components/AnalysisPanel";
import { JDInputPanel } from "@/components/JDInputPanel";
import type { AnalysisPhase, AnalysisResult } from "@/components/types";

const exampleJD = `岗位：TikTok 内容理解策略实习生

你将参与国际化短视频内容生态建设，围绕内容标签、内容理解模型和推荐策略展开分析与协作。

职责：
1. 参与内容标签体系建设，提升内容识别与分发效率。
2. 基于数据分析定位内容理解问题，推动模型和策略迭代。
3. 与算法、产品、运营团队协作，推进内容生态治理和体验优化。
4. 输出结构化分析报告，支持跨区域业务决策。

要求：
- 熟悉 SQL 和基础数据分析方法。
- 对内容产品、推荐系统或大模型应用有兴趣。
- 具备英文沟通能力和跨团队协作意识。
- 有内容策略、模型训练或国际化产品经验优先。`;

const mockResult: AnalysisResult = {
  role: "TikTok 内容理解策略实习生",
  profile: ["AI内容策略方向", "内容理解方向", "国际化产品方向"],
  match: 82,
  responsibilities: [
    "内容标签体系建设",
    "内容理解模型迭代",
    "跨团队协作推进",
  ],
  coreSkills: ["SQL", "数据分析", "内容理解", "模型训练", "英文沟通", "跨团队协作"],
  keywords: ["TikTok", "内容生态", "国际化", "大模型", "推荐系统"],
  gaps: ["A/B测试", "增长分析", "内容策略经验"],
};

export function CareerWorkspace() {
  const [jd, setJd] = useState("");
  const [phase, setPhase] = useState<AnalysisPhase>("idle");
  const [activeStep, setActiveStep] = useState(-1);

  const isAnalyzing = phase === "analyzing";

  useEffect(() => {
    if (!isAnalyzing) {
      return;
    }

    const stepTimers = [0, 400, 800, 1200, 1600].map((delay, index) =>
      window.setTimeout(() => setActiveStep(index), delay),
    );
    const doneTimer = window.setTimeout(() => {
      setPhase("done");
      setActiveStep(4);
    }, 2100);

    return () => {
      stepTimers.forEach((timer) => window.clearTimeout(timer));
      window.clearTimeout(doneTimer);
    };
  }, [isAnalyzing]);

  function handleAnalyze() {
    setPhase("analyzing");
    setActiveStep(-1);
  }

  function handleUseExample() {
    setJd(exampleJD);
    setPhase("idle");
    setActiveStep(-1);
  }

  return (
    <div className="mx-auto grid w-full max-w-7xl gap-5 px-5 pb-8 sm:px-8 lg:grid-cols-[minmax(0,1fr)_minmax(380px,0.92fr)] lg:px-10">
      <JDInputPanel
        jd={jd}
        isAnalyzing={isAnalyzing}
        onAnalyze={handleAnalyze}
        onChange={setJd}
        onUseExample={handleUseExample}
      />
      <AnalysisPanel
        activeStep={activeStep}
        phase={phase}
        result={mockResult}
      />
    </div>
  );
}
